INSERT INTO `t_team` VALUES (1, '胡桃蒸发队', '重击蒸发 · 高额单体爆发', '行秋+夜兰双水挂水 → 钟离开盾减抗 → 胡桃 E 后重击蒸发，双水共鸣提升生命与充能。', 0, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (2, '迪卢克融化队', '融化蒸发 · 火系站场', '班尼特 Q 加攻 → 万叶扩散减抗 → 行秋挂水 → 迪卢克 E+Q 三段融化蒸发。', 1, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (3, '可莉蒸发队', '站场蒸发 · 诡雷输出', '双水挂水 → 班尼特加攻 → 可莉重击与诡雷稳定蒸发，双火共鸣加攻。', 2, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (4, '宵宫蒸发队', '普攻蒸发 · 对单极强', '钟离开盾保站场 → 行秋+夜兰双水挂水 → 宵宫 E 附魔普攻连射蒸发。', 3, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (5, '林尼纯火队', '蓄力箭 · 纯火叠层', '三火共鸣加攻 → 万叶减抗 → 班尼特加攻 → 林尼蓄力箭+猫猫弹叠层输出。', 4, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (6, '阿蕾奇诺蒸发队', '战技叠层 · 蒸发爆发', '班尼特加攻 → 双水挂水 → 阿蕾奇诺 E 叠层后重击蒸发爆发。', 5, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (7, '玛薇卡战舰', '火神爆发 · 纳塔体系', '希诺宁减抗 → 茜特菈莉挂冰 → 班尼特加攻 → 玛薇卡 Q 战意爆发收割，危战最优解。', 6, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (8, '杜林双魔导', '风火混伤 · 破盾利器', '6.6 魔导套质变，风火混伤破盾优势大，法尔伽+杜林双核输出，环境适应力强。', 7, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (9, '达达利亚国际队', '断流蒸发 · 万班香体系', '班尼特加攻 → 万叶减抗 → 香菱挂火 → 公子开 E 断流蒸发，经典万达国际队。', 8, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (10, '神里绫人水队', '站场水伤 · 攻速输出', '万叶减抗 → 班尼特加攻 → 夜兰增伤 → 绫人 E 站场水伤连斩，蒸发增伤。', 9, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (11, '那维莱特纯水队', '重击水炮 · 纯色输出', '芙宁娜 Q 增伤 → 万叶扩散减抗 → 心海治疗保层 → 那维莱特重击水炮群伤。', 10, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (12, '玛拉妮蒸发队', '冲浪蒸发 · 高额爆发', '希诺宁减抗 → 班尼特加攻 → 香菱挂火 → 玛拉妮冲浪蒸发爆发。', 11, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (13, '刻晴激化队', '激化 · 高机动输出', '纳西妲挂草 → 菲谢尔后台雷 → 钟离开盾 → 刻晴 E+Q 激化高机动输出。', 12, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (14, '雷电将军爆发队', '雷九万班 · 一刀收割', '九条 E+Q 增攻 → 班尼特 Q 加攻 → 万叶扩散 → 雷神 Q 一刀收割，经典雷九万班。', 13, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (15, '赛诺激化队', '激化 · 长轴站场', '纳西妲+白术双草 → 菲谢尔后台雷 → 赛诺 Q 长轴激化站场，白术保生存。', 14, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (16, '克洛琳德突进队', '突进雷伤 · 生命契约', '纳西妲挂草 → 菲谢尔后台雷 → 白术治疗 → 克洛琳德 E 突进激化输出。', 15, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (17, '瓦蕾莎站场队', '站场雷伤 · 下落输出', '纳西妲挂草 → 菲谢尔后台雷 → 钟离开盾 → 瓦蕾莎站场激化输出。', 16, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (18, '菲林斯月感电队', '月感电 · 站场主C', '伊涅芙护盾+月感电 → 菈乌玛挂草 → 爱诺水兆 → 菲林斯站场驱动月感电，输出丝滑。', 17, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (19, '米提亚星超导队', '星超导 · 后台雷伤', '奥黛塔挂冰触发星超导 → 瓦列里护盾增超导 → 米提亚战技+大招后台雷伤，至冬三战舰上限最高。', 18, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (20, '甘雨永冻队', '范围永冻 · 蓄力狙杀', '心海挂水 → 万叶聚怪 → 申鹤增冰伤 → 甘雨远程蓄力箭逐个点名，永冻控场。', 19, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (21, '优菈物理队', '物理爆发 · 核弹流', '雷神后台超导减物抗 → 罗莎莉亚暴击拐 → 班尼特加攻 → 优菈 E+Q 核弹爆发。', 20, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (22, '神里绫华永冻队', '神鹤万心 · 冻结爆发', '心海挂水 → 万叶聚怪 → 申鹤 E 增冰伤 → 绫华霰步贴脸 Q+重击，经典神鹤万心。', 21, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (23, '莱欧斯利站场队', '站场冰伤 · 近战拳击', '爱可菲减抗 → 芙宁娜增伤挂水 → 心海治疗 → 莱欧斯利站场冰伤拳击。', 22, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (24, '丝柯克冰水战舰', '冰水协同 · 断流爆发', '爱可菲减抗增伤 → 芙宁娜增伤挂水 → 申鹤增冰伤 → 丝柯克断流引爆，至冬冰C天花板。', 23, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (25, '洛恩站场队', '站场冰伤 · 至冬输出', '爱可菲减抗 → 芙宁娜增伤 → 奥黛塔挂冰 → 洛恩站场冰伤输出。', 24, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (26, '魈下落队', '下落攻击 · 风伤爆发', '珐露珊风伤减抗 → 班尼特加攻 → 钟离开盾 → 魈 Q 后连续下落攻击爆发。', 25, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (27, '流浪者风队', '站场风伤 · 高机动', '珐露珊风伤减抗 → 班尼特加攻 → 钟离开盾 → 流浪者 E 站场风伤高机动输出。', 26, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (28, '恰斯卡多元素队', '多元素 · 龙息输出', '芙宁娜增伤 → 班尼特加攻 → 欧洛伦后台雷 → 恰斯卡多元素龙息输出。', 27, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (29, '法尔伽双魔导队', '风火混伤 · 双持输出', '6.6 魔导套质变，法尔伽+杜林双核风火混伤，布伦妮增风伤、尼可增火伤，破盾优势大。', 28, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (30, '薇斯纳星扩散队', '星扩散 · 浮空输出', '奥黛塔挂冰触发星扩散 → 沃雅妮莎减抗治疗 → 珐露珊风伤拐 → 薇斯纳浮空星扩散输出。', 29, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (31, '荒泷一斗岩队', '站场岩伤 · 重击输出', '纯岩队：五郎增岩伤 → 阿贝多后台 → 钟离开盾 → 一斗 Q 后重击爆发，三岩共鸣。', 30, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (32, '娜维娅结晶队', '结晶弹片 · 爆发输出', '双岩共鸣 → 班尼特加攻 → 香菱挂火产结晶 → 娜维娅收集弹片 E 炮击。', 31, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (33, '兹白月结晶队', '月结晶 · 岩系完全体', '叶洛亚+希诺宁增岩减抗 → 钟离开盾 → 兹白月结晶爆发，岩系数值怪跨环境执法。', 32, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (34, '提纳里激化队', '激化 · 蓄力箭输出', '纳西妲挂草 → 菲谢尔+八重后台雷 → 提纳里蓄力箭激化输出。', 33, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (35, '艾尔海森激化队', '站场激化 · 光幕输出', '纳西妲挂草 → 菲谢尔后台雷 → 白术治疗 → 艾尔海森 E+光幕站场激化。', 34, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
INSERT INTO `t_team` VALUES (36, '基尼奇燃烧队', '燃烧 · 高爆发输出', '纳西妲挂草 → 班尼特+迪希雅触发燃烧 → 基尼奇燃烧高爆发。', 35, 1, '2026-11-02 09:46:00', '2026-11-02 09:46:00');
